        setPurchases(sortedPurchases);
        setLoading(false);
        setTotalValue(calculateTotalValue());
      } catch (error) {
        console.log(error);
      }
    };
    fetchData();
  }, [refresh]);

  async function getTrackingStatus(trackingCode) {
    try {
      const response = await api.get(`/rastreio/${trackingCode}`);
      return response.data;
    } catch (error) {
      console.error(error);
    }
